// ============================================================
// Orbit DevOps - Frontend Application
// AI-native DevOps dashboard with chat interface
// ============================================================

import React, { useState, useEffect, useCallback, useRef } from 'react';
import './index.css';
import orbitApi, { FlowExecution, ChatMessage } from './services/api';

// Generate a session ID for chat
const SESSION_ID = `session-${Date.now()}`;

function App() {
  // State
  const [activeTab, setActiveTab] = useState<'dashboard' | 'chat' | 'activity'>('dashboard');
  const [health, setHealth] = useState<any>(null);
  const [agents, setAgents] = useState<any[]>([]);
  
  // Chat state
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  
  // Execution state
  const [currentExecutionId, setCurrentExecutionId] = useState<string | null>(null);
  const [execution, setExecution] = useState<FlowExecution | null>(null);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  
  // Quick action state
  const [quickAction, setQuickAction] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [quickActionMessage, setQuickActionMessage] = useState('');
  
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Check health on mount
  useEffect(() => {
    checkHealth();
    loadAgents();
    loadSuggestions();
  }, []);

  // Poll execution status when running
  useEffect(() => {
    if (!currentExecutionId) return;

    const interval = setInterval(async () => {
      try {
        const status = await orbitApi.getExecutionStatus(currentExecutionId);
        setExecution(status);

        if (status.status === 'completed' || status.status === 'failed') {
          clearInterval(interval);
          
          // Add system message about completion
          if (status.status === 'completed') {
            addMessage({
              id: Date.now().toString(),
              role: 'system',
              content: status.result?.userMessage || 'Operation completed!',
              timestamp: new Date().toISOString()
            });
          } else {
            addMessage({
              id: Date.now().toString(),
              role: 'system',
              content: `Something went wrong: ${status.error || 'Unknown error'}`,
              timestamp: new Date().toISOString()
            });
          }
        }
      } catch (error) {
        console.error('Status poll error:', error);
      }
    }, 2000);

    return () => clearInterval(interval);
  }, [currentExecutionId]);

  // Auto-scroll chat
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const checkHealth = async () => {
    try {
      const data = await orbitApi.checkHealth();
      setHealth(data);
    } catch (error) {
      setHealth({ status: 'error', services: { gitlab: 'unavailable' } });
    }
  };

  const loadAgents = async () => {
    try {
      const data = await orbitApi.getAgents();
      setAgents(data.agents || []);
    } catch (error) {
      console.error('Failed to load agents:', error);
    }
  };

  const loadSuggestions = async () => {
    try {
      const data = await orbitApi.getSuggestions();
      setSuggestions(data.suggestions || []);
    } catch (error) {
      setSuggestions([
        'Deploy my app',
        'Build my app',
        'Fix the broken build',
        'Add a feature and deploy it'
      ]);
    }
  };

  const addMessage = (message: ChatMessage) => {
    setMessages(prev => [...prev, message]);
  };

  // Handle chat message send
  const handleSendMessage = async () => {
    if (!inputMessage.trim() || isChatLoading) return;

    const userMessage = inputMessage.trim();
    setInputMessage('');
    setIsChatLoading(true);

    // Add user message
    addMessage({
      id: Date.now().toString(),
      role: 'user',
      content: userMessage,
      timestamp: new Date().toISOString()
    });

    try {
      const response = await orbitApi.sendMessage(userMessage, SESSION_ID);
      
      // Add system response
      addMessage({
        id: (Date.now() + 1).toString(),
        role: 'system',
        content: response.response,
        timestamp: new Date().toISOString(),
        metadata: { intent: response.intent, executionId: response.executionId }
      });

      // Track execution for polling
      if (response.executionId) {
        setCurrentExecutionId(response.executionId);
      }
    } catch (error: any) {
      addMessage({
        id: (Date.now() + 1).toString(),
        role: 'system',
        content: error.response?.data?.message || error.message || 'Failed to process your request',
        timestamp: new Date().toISOString()
      });
    } finally {
      setIsChatLoading(false);
    }
  };

  // Quick action handlers
  const handleDeploy = useCallback(async () => {
    setQuickAction('loading');
    setQuickActionMessage('Starting deployment...');
    
    try {
      const response = await orbitApi.sendMessage('Deploy my app to staging', SESSION_ID);
      if (response.executionId) {
        setCurrentExecutionId(response.executionId);
        setQuickActionMessage('Deployment in progress...');
      }
    } catch (error: any) {
      setQuickAction('error');
      setQuickActionMessage(error.message || 'Deployment failed');
    }
  }, []);

  const handleBuild = useCallback(async () => {
    setQuickAction('loading');
    setQuickActionMessage('Building your app...');
    
    try {
      const response = await orbitApi.sendMessage('Build my app', SESSION_ID);
      if (response.executionId) {
        setCurrentExecutionId(response.executionId);
        setQuickActionMessage('Build in progress...');
      }
    } catch (error: any) {
      setQuickAction('error');
      setQuickActionMessage(error.message || 'Build failed');
    }
  }, []);

  const handleFix = useCallback(async () => {
    setQuickAction('loading');
    setQuickActionMessage('Analyzing and fixing issues...');
    
    try {
      const response = await orbitApi.sendMessage('Fix my app', SESSION_ID);
      if (response.executionId) {
        setCurrentExecutionId(response.executionId);
        setQuickActionMessage('Fix in progress...');
      }
    } catch (error: any) {
      setQuickAction('error');
      setQuickActionMessage(error.message || 'Fix failed');
    }
  }, []);

  const handleTest = useCallback(async () => {
    setQuickAction('loading');
    setQuickActionMessage('Running tests...');
    
    try {
      const response = await orbitApi.sendMessage('Run the tests', SESSION_ID);
      if (response.executionId) {
        setCurrentExecutionId(response.executionId);
        setQuickActionMessage('Tests in progress...');
      }
    } catch (error: any) {
      setQuickAction('error');
      setQuickActionMessage(error.message || 'Tests failed');
    }
  }, []);

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'completed':
      case 'success':
      case 'passed':
        return '✓';
      case 'running':
      case 'pending':
        return '⟳';
      case 'failed':
        return '✗';
      default:
        return '○';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed':
      case 'success':
      case 'passed':
        return 'var(--orbit-accent-green)';
      case 'running':
      case 'pending':
        return 'var(--orbit-accent-blue)';
      case 'failed':
        return 'var(--orbit-accent-red)';
      default:
        return 'var(--orbit-text-secondary)';
    }
  };

  return (
    <div className="app">
      {/* Header */}
      <header className="header">
        <div className="logo">
          <span className="logo-icon">🚀</span>
          <h1>Orbit DevOps</h1>
        </div>
        <div className="header-actions">
          <div className="health-indicator">
            <span className={`health-dot ${health?.status === 'healthy' ? 'healthy' : 'error'}`}></span>
            <span className="health-text">
              {health?.status === 'healthy' ? 'System Ready' : 'Connecting...'}
            </span>
          </div>
        </div>
      </header>

      {/* Navigation */}
      <nav className="nav">
        <button 
          className={`nav-button ${activeTab === 'dashboard' ? 'active' : ''}`}
          onClick={() => setActiveTab('dashboard')}
        >
          📊 Dashboard
        </button>
        <button 
          className={`nav-button ${activeTab === 'chat' ? 'active' : ''}`}
          onClick={() => setActiveTab('chat')}
        >
          💬 Ask Orbit
        </button>
        <button 
          className={`nav-button ${activeTab === 'activity' ? 'active' : ''}`}
          onClick={() => setActiveTab('activity')}
        >
          📜 Activity
        </button>
      </nav>

      {/* Main Content */}
      <main className="main">
        {/* Dashboard Tab */}
        {activeTab === 'dashboard' && (
          <div className="dashboard">
            {/* Quick Actions */}
            <section className="panel quick-actions">
              <h2>What would you like to do?</h2>
              <div className="action-buttons">
                <button 
                  className={`action-btn deploy ${quickAction === 'loading' ? 'loading' : ''}`}
                  onClick={handleDeploy}
                  disabled={quickAction === 'loading'}
                >
                  <span className="action-icon">🚀</span>
                  Deploy App
                </button>
                <button 
                  className="action-btn build"
                  onClick={handleBuild}
                  disabled={quickAction === 'loading'}
                >
                  <span className="action-icon">🔨</span>
                  Build App
                </button>
                <button 
                  className="action-btn fix"
                  onClick={handleFix}
                  disabled={quickAction === 'loading'}
                >
                  <span className="action-icon">🔧</span>
                  Fix Issues
                </button>
                <button 
                  className="action-btn test"
                  onClick={handleTest}
                  disabled={quickAction === 'loading'}
                >
                  <span className="action-icon">✓</span>
                  Run Tests
                </button>
              </div>
              {quickActionMessage && (
                <div className={`quick-status ${quickAction}`}>
                  {quickAction === 'loading' && <span className="spinner"></span>}
                  {quickAction === 'success' && '✓'}
                  {quickAction === 'error' && '✗'}
                  {quickActionMessage}
                </div>
              )}
            </section>

            {/* Project Status */}
            <section className="panel project-status">
              <h3>Project Status</h3>
              <div className="status-grid">
                <div className="status-item">
                  <span className="status-label">Last Deployment</span>
                  <span className="status-value success">✓ Successful</span>
                </div>
                <div className="status-item">
                  <span className="status-label">Environment</span>
                  <span className="status-value">Staging</span>
                </div>
                <div className="status-item">
                  <span className="status-label">Version</span>
                  <span className="status-value">v1.0.0</span>
                </div>
                <div className="status-item">
                  <span className="status-label">Tests</span>
                  <span className="status-value success">24/24 Passed</span>
                </div>
              </div>
            </section>

            {/* Active Agents */}
            <section className="panel agents-panel">
              <h3>Active Agents</h3>
              <div className="agents-grid">
                {agents.map((agent, i) => (
                  <div key={i} className="agent-card">
                    <div className="agent-icon">
                      {agent.type === 'code-agent' && '📝'}
                      {agent.type === 'git-agent' && '📚'}
                      {agent.type === 'cicd-agent' && '⚙️'}
                      {agent.type === 'debug-agent' && '🔧'}
                      {agent.type === 'deploy-agent' && '🚀'}
                      {agent.type === 'security-agent' && '🔒'}
                    </div>
                    <div className="agent-info">
                      <span className="agent-name">{agent.name}</span>
                      <span className="agent-desc">{agent.description}</span>
                    </div>
                    <span className="agent-status available">Available</span>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}

        {/* Chat Tab */}
        {activeTab === 'chat' && (
          <div className="chat-container">
            <div className="chat-messages">
              {messages.length === 0 && (
                <div className="chat-empty">
                  <p>👋 Hi! I'm Orbit, your AI DevOps assistant.</p>
                  <p>Tell me what you want to do, like:</p>
                  <div className="suggestion-chips">
                    {suggestions.slice(0, 4).map((suggestion, i) => (
                      <button
                        key={i}
                        className="suggestion-chip"
                        onClick={() => {
                          setInputMessage(suggestion);
                        }}
                      >
                        {suggestion}
                      </button>
                    ))}
                  </div>
                </div>
              )}
              {messages.map((msg, i) => (
                <div key={i} className={`chat-message ${msg.role}`}>
                  <div className="message-content">
                    {msg.content}
                  </div>
                  <div className="message-time">
                    {new Date(msg.timestamp).toLocaleTimeString()}
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>
            <div className="chat-input">
              <input
                type="text"
                placeholder="Type what you want to do..."
                value={inputMessage}
                onChange={(e) => setInputMessage(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
                disabled={isChatLoading}
              />
              <button 
                onClick={handleSendMessage}
                disabled={isChatLoading || !inputMessage.trim()}
              >
                {isChatLoading ? '...' : '→'}
              </button>
            </div>
          </div>
        )}

        {/* Activity Tab */}
        {activeTab === 'activity' && (
          <div className="activity-container">
            {/* Current Execution */}
            {execution && (
              <section className="panel execution-panel">
                <h3>Current Operation</h3>
                <div className="execution-header">
                  <span className="execution-name">{execution.flowName}</span>
                  <span 
                    className="execution-status"
                    style={{ color: getStatusColor(execution.status) }}
                  >
                    {getStatusIcon(execution.status)} {execution.status}
                  </span>
                </div>
                
                {/* Progress */}
                <div className="progress-steps">
                  {execution.progress?.map((step, i) => (
                    <div 
                      key={i} 
                      className={`progress-step ${step.status}`}
                    >
                      <div className="step-indicator">
                        {getStatusIcon(step.status)}
                      </div>
                      <div className="step-content">
                        <span className="step-name">{step.stage}</span>
                        {step.message && <span className="step-message">{step.message}</span>}
                      </div>
                    </div>
                  ))}
                </div>
              </section>
            )}

            {/* Activity Log */}
            <section className="panel log-panel">
              <h3>Activity Log</h3>
              <div className="activity-log">
                {execution?.logs?.length === 0 && (
                  <p className="empty-state">No activity yet</p>
                )}
                {execution?.logs?.map((log, i) => (
                  <div key={i} className="log-entry">
                    <span className="log-time">
                      {new Date(execution.startTime).toLocaleTimeString()}
                    </span>
                    <span className="log-text">{log}</span>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="footer">
        <p>Orbit DevOps - AI-Native Deployment Platform</p>
      </footer>
    </div>
  );
}

export default App;
